/* 下线指挥台 · 流程数据（内联随首屏就绪，无任何异步加载） */
window.RUNBOOK = {
  meta: {
    changeId: "CHG-20260919-0417",
    title: "生产服务器安全下线",
    target: "prod-app-07 · 10.20.8.17 · 应用集群 C",
    executor: "值班工程师",
    window: "变更窗口 2026-09-19 22:00 – 23:30",
    policy: "零失误走完全程：门禁未过不放行；不可逆动作先确认后果、后留恢复路径。"
  },
  phases: [
    {
      id: "p1",
      num: 1,
      title: "准备",
      summary: "核对信息、留好基线，把人叫齐。",
      steps: [
        {
          id: "s1",
          title: "核对变更单与执行窗口",
          instruction: "逐项核对本页信息与工单系统一致：变更单号、目标机器、执行窗口。任何一项不符，立即停止并上报值班经理。",
          checks: [
            "已核对变更单号 CHG-20260919-0417 与工单一致",
            "已核对目标机器 prod-app-07（10.20.8.17）与工单一致",
            "当前时间处于变更窗口内"
          ],
          irrev: null
        },
        {
          id: "s2",
          title: "记录监控基线",
          instruction: "在监控台截取并归档当前基线，作为下线前后容量与流量的对比依据。",
          checks: [
            "已记录 CPU 与内存使用基线",
            "已记录最近 15 分钟请求量曲线"
          ],
          irrev: null
        },
        {
          id: "s3",
          title: "通知相关方",
          instruction: "下线开始前，让所有相关方知情。漏通知是下线事故的最常见起因。",
          checks: [
            "已在值班群通报『prod-app-07 下线开始』",
            "已通知业务方值班人并获知悉回复"
          ],
          irrev: null
        }
      ]
    },
    {
      id: "p2",
      num: 2,
      title: "摘除",
      summary: "先断流量，等排空，确认零流量后再进入销毁。",
      steps: [
        {
          id: "s4",
          title: "从负载均衡摘除节点",
          instruction: "在负载均衡控制台将 prod-app-07 移出转发池。摘除后线上容量减少 1/4。",
          checks: [
            "已确认集群剩余 3 节点全部健康",
            "已确认当前总流量低于摘除阈值（QPS < 1200）"
          ],
          irrev: {
            kind: "undoable",
            undoSeconds: 30,
            consequence: "节点立即停止接收新流量，线上容量减少 1/4。若剩余节点异常，将出现容量告警。",
            recovery: "执行后 30 秒内可一键【撤销摘除】，节点回加并恢复接流；窗口关闭后需走负载均衡变更单回加（约 10 分钟）。"
          }
        },
        {
          id: "s5",
          title: "等待连接排空",
          instruction: "摘除只影响新连接。等待存量连接自然结束，确认排空进度后再继续。",
          checks: [
            "该节点活动连接数 ≤ 5",
            "已等待至少 120 秒排空期"
          ],
          irrev: null
        },
        {
          id: "s6",
          title: "确认零流量",
          instruction: "以监控台为准确认该节点已无任何业务流量，才允许进入销毁阶段。",
          checks: [
            "监控台该节点 QPS 为 0 且已持续 60 秒",
            "无残留定时任务产生内网调用"
          ],
          irrev: null
        }
      ]
    },
    {
      id: "p3",
      num: 3,
      title: "销毁",
      summary: "先落快照（唯一恢复点），再停机、抹盘。本阶段含最强不可逆动作。",
      steps: [
        {
          id: "s7",
          title: "确认最终快照完成",
          instruction: "快照系统已自动产出最终快照 bk-20260919-final。这是后续抹盘动作的唯一恢复点，必须先确认可用。",
          checks: [
            "快照 bk-20260919-final 状态为『可用』",
            "已将快照 ID 抄录至工单备注"
          ],
          irrev: null
        },
        {
          id: "s8",
          title: "关闭服务器电源",
          instruction: "通过带外管理口（BMC）对 prod-app-07 执行软关机，避免文件系统损伤。",
          checks: [
            "已确认机器上无仍在运行的任务",
            "已通过 BMC 发出软关机指令"
          ],
          irrev: {
            kind: "undoable",
            undoSeconds: 45,
            consequence: "服务器关机，集群 C 失去热备节点。关机期间无法通过应用层探活。",
            recovery: "执行后 45 秒内可通过【撤销关机】重新开机；窗口关闭后仍可再次开机恢复（恢复路径：BMC 电源操作，约 3 分钟）。"
          }
        },
        {
          id: "s9",
          title: "抹除数据盘",
          instruction: "对数据盘 /dev/sdb 执行三遍覆写抹除。此动作完成后，本机数据不可恢复，只能依赖快照。",
          checks: [
            "已二次核对目标盘为 /dev/sdb（非系统盘）",
            "已再次确认快照 bk-20260919-final 可读"
          ],
          irrev: {
            kind: "final",
            consequence: "数据盘被覆写抹除，本机数据永久不可恢复。抹除过程约 40 分钟，期间机器不可复用。",
            recovery: "唯一恢复路径：使用快照 bk-20260919-final 恢复数据到新盘（约 2 小时）。抹除完成后请立即抽验快照可读性。"
          }
        }
      ]
    },
    {
      id: "p4",
      num: 4,
      title: "收尾",
      summary: "摘干净监控、更新台账、归档关单。",
      steps: [
        {
          id: "s10",
          title: "注销监控与告警",
          instruction: "移除该节点的监控采集项，静默相关告警规则，避免下线后出现无效告警。",
          checks: [
            "已移除该节点全部监控采集项",
            "已静默引用 10.20.8.17 的告警规则"
          ],
          irrev: null
        },
        {
          id: "s11",
          title: "更新资产台账",
          instruction: "在资产系统中将 ASM-0717 标记为『已下线-待处置』，该标记将自动触发处置审批流。",
          checks: [
            "已核对资产编号 ASM-0717 与机器一致",
            "已确认台账中责任人字段已更新"
          ],
          irrev: {
            kind: "final",
            consequence: "台账状态变更为『已下线-待处置』，自动触发资产处置审批流，机器进入待回收队列。",
            recovery: "30 天内可在资产系统提交『台账变更回退单』恢复『在役』状态（需值班经理审批，约 1 个工作日）。"
          }
        },
        {
          id: "s12",
          title: "归档记录并关单",
          instruction: "核对本页执行记录完整（含确认门与恢复路径记录），归档后在工单系统关闭变更单。",
          checks: [
            "本页执行记录已含全部不可逆动作的确认与恢复记录",
            "已在工单填写完成备注并关单"
          ],
          irrev: null
        }
      ]
    }
  ]
};

