/* 下线指挥台 · 设计令牌与布局 */
:root {
  --bg: #edf0f5;
  --surface: #ffffff;
  --surface-2: #f7f9fc;
  --ink: #1b2636;
  --ink-2: #46566c;
  --muted: #6b7a90;
  --line: #d9e1ec;
  --line-2: #e7edf5;

  --primary: #2456d6;
  --primary-strong: #1d47b4;
  --primary-soft: #e8eefc;

  --ok: #0e8a4d;
  --ok-soft: #e5f5ec;
  --warn: #b45309;
  --warn-soft: #fff6e9;
  --warn-line: #f2c98a;
  --danger: #c22736;
  --danger-strong: #a51f2d;
  --danger-soft: #fdecec;

  --header-ink: #16233b;

  --radius: 10px;
  --radius-sm: 7px;
  --shadow: 0 1px 2px rgba(22, 35, 59, .06), 0 8px 24px rgba(22, 35, 59, .07);

  --font: "Segoe UI", "PingFang SC", "Microsoft YaHei", "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, Consolas, "Cascadia Mono", Menlo, monospace;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }

body {
  font-family: var(--font);
  font-size: 14px;
  line-height: 1.6;
  color: var(--ink);
  background:
    linear-gradient(180deg, #e6ebf3 0%, var(--bg) 240px);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ---------- 顶栏 ---------- */
.app-header {
  background: var(--header-ink);
  color: #fff;
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 12px 28px;
  position: sticky;
  top: 0;
  z-index: 30;
}

.brand { display: flex; align-items: center; gap: 12px; min-width: 220px; }
.brand-mark {
  width: 38px; height: 38px; border-radius: 9px;
  background: linear-gradient(135deg, #2e63e6, #1b3f9e);
  display: grid; place-items: center; color: #fff;
  flex: none;
}
.brand-name { font-size: 16px; font-weight: 700; letter-spacing: .5px; }
.brand-sub { font-size: 12px; color: #9fb0cc; font-family: var(--mono); }

.header-meta { flex: 1; display: flex; gap: 20px; flex-wrap: wrap; font-size: 12.5px; color: #c3cfe4; }
.header-meta b { color: #fff; font-weight: 600; }

.header-actions { display: flex; align-items: center; gap: 10px; }

.dev-badge {
  font-size: 12.5px; font-weight: 700;
  padding: 4px 12px; border-radius: 999px;
  transition: background .2s, color .2s;
}
.dev-badge.is-ok { background: rgba(20, 160, 96, .18); color: #58d69a; }
.dev-badge.is-bad { background: rgba(226, 74, 74, .2); color: #ff9d9d; }
.dev-badge.pulse { animation: pulse .5s ease; }
@keyframes pulse { 0% { transform: scale(1); } 40% { transform: scale(1.18); } 100% { transform: scale(1); } }

/* ---------- 按钮 ---------- */
.btn {
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 600;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  padding: 8px 18px;
  cursor: pointer;
  transition: background .15s, border-color .15s, box-shadow .15s;
}
.btn.sm { padding: 4px 12px; font-size: 12.5px; }
.btn.primary { background: var(--primary); color: #fff; }
.btn.primary:hover { background: var(--primary-strong); }
.btn.danger { background: var(--danger); color: #fff; }
.btn.danger:hover { background: var(--danger-strong); }
.btn.ghost { background: transparent; color: var(--ink-2); border-color: var(--line); }
.btn.ghost:hover { background: var(--surface-2); }
.btn.ghost.on-dark { color: #cdd9ee; border-color: rgba(255,255,255,.28); }
.btn.ghost.on-dark:hover { background: rgba(255,255,255,.08); }
.btn.ghost.on-dark.danger-text:hover { color: #ff9d9d; border-color: rgba(255,157,157,.5); }
.btn.ok { background: var(--ok); color: #fff; }
.btn.ok:hover { background: #0b7340; }
.btn:disabled { opacity: .45; cursor: not-allowed; }
.btn:disabled:hover { background: var(--danger); }

/* ---------- 撤销窗口横条 ---------- */
.undo-strip {
  background: var(--warn-soft);
  border-bottom: 1px solid var(--warn-line);
  color: #7a4106;
  padding: 8px 28px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  position: sticky;
  top: 62px;
  z-index: 25;
}
.undo-item { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; font-size: 13px; }
.undo-item .u-title { font-weight: 700; }
.undo-item .u-count { font-family: var(--mono); font-weight: 700; color: #9a4d00; }
.undo-item .u-hint { color: #a06414; font-size: 12px; }
.undo-item .spacer { flex: 1; }
.undo-ico { color: var(--warn); display: grid; place-items: center; }

/* ---------- 主布局 ---------- */
.layout {
  flex: 1;
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 28px 28px 40px;
  display: grid;
  grid-template-columns: 320px minmax(0, 1fr);
  gap: 24px;
  align-items: start;
}

/* ---------- 旅程图（列表侧） ---------- */
.journey {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 8px 0 16px;
  position: sticky;
  top: 86px;
}
.journey-head {
  padding: 14px 18px 10px;
  border-bottom: 1px solid var(--line-2);
  margin-bottom: 8px;
}
.journey-head .jt { font-size: 13px; font-weight: 700; color: var(--ink-2); letter-spacing: 1px; }
.journey-head .jmeta { font-size: 12px; color: var(--muted); margin-top: 2px; }

.jphase { margin-top: 6px; }
.jphase-head {
  display: flex; align-items: center; gap: 8px;
  padding: 10px 18px 4px;
}
.jpnum {
  font-size: 11px; font-weight: 700; color: var(--primary);
  background: var(--primary-soft);
  border-radius: 4px; padding: 1px 7px; letter-spacing: 1px;
}
.jptitle { font-size: 13.5px; font-weight: 700; }
.jpprog { margin-left: auto; font-size: 12px; color: var(--muted); font-family: var(--mono); }

.jlist { list-style: none; margin: 0; padding: 0; }
.jstep {
  width: 100%;
  display: flex; align-items: center; gap: 10px;
  padding: 8px 14px 8px 18px;
  background: none; border: none; border-left: 3px solid transparent;
  font-family: inherit; font-size: 13.5px; color: var(--ink-2);
  text-align: left; cursor: pointer;
}
.jstep:hover { background: var(--surface-2); }
.jstep .jicon { flex: none; display: grid; place-items: center; width: 20px; height: 20px; }
.jstep .jtitle { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.jstep .jflag { flex: none; color: var(--warn); }

.jstep.is-locked { color: #9aa8bc; cursor: not-allowed; }
.jstep.is-locked:hover { background: none; }
.jstep.is-done { color: var(--ink-2); }
.jstep.is-current {
  border-left-color: var(--primary);
  background: var(--primary-soft);
  color: var(--ink);
  font-weight: 600;
}
.jstep.is-viewing { border-left-color: var(--warn); background: var(--warn-soft); }

/* ---------- 执行区（详情侧） ---------- */
.focus-col { min-width: 0; }

.step-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 30px 36px 28px;
}

.crumb {
  display: flex; align-items: center; gap: 8px;
  font-size: 12.5px; color: var(--muted); letter-spacing: .5px;
  margin-bottom: 10px;
}
.crumb .sep { color: var(--line); }

.step-title-row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.step-title { font-size: 23px; font-weight: 700; margin: 0; letter-spacing: .3px; }

.badge {
  font-size: 12px; font-weight: 700;
  padding: 3px 10px; border-radius: 999px;
  display: inline-flex; align-items: center; gap: 5px;
}
.badge.irrev { background: var(--warn-soft); color: var(--warn); border: 1px solid var(--warn-line); }
.badge.done { background: var(--ok-soft); color: var(--ok); }
.badge.readonly { background: var(--surface-2); color: var(--muted); border: 1px solid var(--line); }

.step-instruction { color: var(--ink-2); font-size: 14.5px; margin: 14px 0 22px; max-width: 62ch; }

.section-label {
  font-size: 12.5px; font-weight: 700; letter-spacing: 1.5px;
  color: var(--muted); margin: 0 0 10px;
}

.checks { display: flex; flex-direction: column; gap: 8px; margin: 0 0 24px; }
.check-row {
  display: flex; align-items: flex-start; gap: 10px;
  border: 1px solid var(--line);
  background: var(--surface-2);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  cursor: pointer;
  transition: border-color .15s, background .15s;
}
.check-row:hover { border-color: #bfcde2; }
.check-row input { margin-top: 3px; width: 16px; height: 16px; accent-color: var(--ok); flex: none; }
.check-row.is-checked { background: var(--ok-soft); border-color: #b5e0c8; }
.check-row.is-checked .check-text { color: #14532d; }

/* 不可逆预览（执行前可见：后果 + 恢复路径） */
.irrev-preview {
  border: 1px solid var(--warn-line);
  border-left: 4px solid var(--warn);
  background: var(--warn-soft);
  border-radius: var(--radius-sm);
  padding: 14px 18px;
  margin: 0 0 24px;
}
.irrev-preview .block { margin: 0 0 10px; }
.irrev-preview .block:last-child { margin-bottom: 0; }

.block-label {
  font-size: 12px; font-weight: 800; letter-spacing: 1.5px;
  display: inline-flex; align-items: center; gap: 6px;
  margin-bottom: 3px;
}
.block-label.is-danger { color: var(--danger); }
.block-label.is-safe { color: var(--ok); }
.block p { margin: 0; color: var(--ink-2); font-size: 13.5px; }

/* 操作行 */
.action-row {
  display: flex; align-items: center; gap: 14px;
  border-top: 1px solid var(--line-2);
  padding-top: 20px;
}
.action-hint { color: var(--muted); font-size: 12.5px; flex: 1; }

.gate-error {
  background: var(--danger-soft);
  border: 1px solid #f3b8b8;
  border-radius: var(--radius-sm);
  padding: 12px 16px;
  margin-bottom: 18px;
  color: #7c1d26;
  font-size: 13px;
}
.gate-error ul { margin: 6px 0 0; padding-left: 20px; }
.gate-error .ge-title { font-weight: 700; display: flex; align-items: center; gap: 6px; }

.shake { animation: shake .4s ease; }
@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-5px); }
  50% { transform: translateX(5px); }
  75% { transform: translateX(-3px); }
}

/* 已完成步骤回看 */
.done-record {
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  padding: 14px 18px;
  margin-bottom: 24px;
  display: flex; flex-direction: column; gap: 6px;
  font-size: 13px;
  color: var(--ink-2);
}
.done-record .dr-row { display: flex; gap: 10px; }
.done-record .dr-k { flex: none; width: 88px; color: var(--muted); }
.done-record .dr-v { font-family: var(--mono); }

/* 完成凭证 */
.certificate {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 40px 48px;
  text-align: center;
}
.cert-icon { color: var(--ok); margin-bottom: 8px; }
.cert-title { font-size: 26px; font-weight: 800; margin: 0 0 6px; letter-spacing: 1px; }
.cert-sub { color: var(--muted); font-size: 13.5px; margin: 0 0 24px; }
.cert-zero {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 15px; font-weight: 800;
  padding: 8px 22px; border-radius: 999px;
}
.cert-zero.is-perfect { background: var(--ok-soft); color: var(--ok); border: 1px solid #b5e0c8; }
.cert-zero.is-flawed { background: var(--warn-soft); color: var(--warn); border: 1px solid var(--warn-line); }

.cert-stats {
  display: grid; grid-template-columns: repeat(4, 1fr);
  gap: 12px; margin: 28px 0;
}
.cert-stat {
  background: var(--surface-2);
  border: 1px solid var(--line-2);
  border-radius: var(--radius-sm);
  padding: 14px 8px;
}
.cert-stat .v { font-size: 19px; font-weight: 800; font-family: var(--mono); }
.cert-stat .k { font-size: 12px; color: var(--muted); margin-top: 2px; }

.cert-table-wrap { text-align: left; margin: 0 0 24px; }
.cert-table {
  width: 100%; border-collapse: collapse; font-size: 12.5px;
}
.cert-table caption {
  caption-side: top; text-align: left;
  font-size: 12.5px; font-weight: 700; letter-spacing: 1.5px;
  color: var(--muted); padding-bottom: 8px;
}
.cert-table th, .cert-table td {
  border: 1px solid var(--line-2);
  padding: 8px 10px; text-align: left; vertical-align: top;
}
.cert-table th { background: var(--surface-2); color: var(--ink-2); font-weight: 700; }
.cert-table td.mono { font-family: var(--mono); font-size: 12px; }

.cert-actions { display: flex; justify-content: center; gap: 12px; }

/* ---------- 抽屉（执行记录） ---------- */
.drawer {
  position: fixed; top: 0; right: 0; bottom: 0;
  width: 380px; max-width: 92vw;
  background: var(--surface);
  border-left: 1px solid var(--line);
  box-shadow: -12px 0 32px rgba(22,35,59,.14);
  z-index: 60;
  display: flex; flex-direction: column;
}
.drawer-head {
  display: flex; align-items: center; gap: 10px;
  padding: 16px 18px;
  border-bottom: 1px solid var(--line-2);
}
.drawer-head h2 { font-size: 15px; margin: 0; flex: none; }
.drawer-count { color: var(--muted); font-size: 12px; flex: 1; }

.drawer-empty { padding: 32px 24px; color: var(--muted); font-size: 13px; text-align: center; }

.timeline { list-style: none; margin: 0; padding: 12px 18px 24px; overflow-y: auto; }
.tl-item {
  position: relative;
  padding: 0 0 16px 26px;
  font-size: 13px;
}
.tl-item::before {
  content: "";
  position: absolute; left: 6px; top: 6px; bottom: -2px;
  width: 2px; background: var(--line-2);
}
.tl-item:last-child::before { display: none; }
.tl-dot {
  position: absolute; left: 0; top: 4px;
  width: 14px; height: 14px; border-radius: 50%;
  display: grid; place-items: center;
  background: var(--surface); border: 2px solid var(--muted);
}
.tl-item.k-execute .tl-dot { border-color: var(--ok); }
.tl-item.k-confirm .tl-dot { border-color: var(--warn); }
.tl-item.k-deviation .tl-dot { border-color: var(--danger); }
.tl-item.k-undo .tl-dot { border-color: var(--primary); }
.tl-item.k-done .tl-dot { border-color: var(--ok); }
.tl-time { font-family: var(--mono); font-size: 11.5px; color: var(--muted); }
.tl-text { color: var(--ink-2); }

/* ---------- 确认门（模态） ---------- */
.scrim {
  position: fixed; inset: 0;
  background: rgba(13, 20, 33, .5);
  z-index: 70;
}
.modal {
  position: fixed; inset: 0;
  display: grid; place-items: center;
  z-index: 80;
  padding: 24px;
}
.modal-card {
  width: 560px; max-width: 100%;
  background: var(--surface);
  border-radius: 14px;
  box-shadow: 0 24px 64px rgba(10, 16, 28, .35);
  overflow: hidden;
}
.modal-head {
  padding: 20px 26px 14px;
  border-bottom: 1px solid var(--line-2);
}
.modal-kicker {
  font-size: 12px; font-weight: 800; letter-spacing: 2px;
  color: var(--danger);
}
.modal-head h2 { font-size: 19px; margin: 6px 0 0; }
.modal-body { padding: 20px 26px; display: flex; flex-direction: column; gap: 14px; }
.modal-body .block {
  border-radius: var(--radius-sm);
  padding: 12px 16px;
  border: 1px solid var(--line);
}
.consequence-block { background: var(--danger-soft); border-color: #f3b8b8; }
.recovery-block { background: var(--ok-soft); border-color: #b5e0c8; }
.ack-row {
  display: flex; align-items: flex-start; gap: 10px;
  font-size: 13.5px; color: var(--ink);
  cursor: pointer; padding: 4px 2px;
}
.ack-row input { width: 17px; height: 17px; margin-top: 2px; accent-color: var(--danger); flex: none; }
.modal-actions {
  display: flex; justify-content: flex-end; gap: 12px;
  padding: 16px 26px 22px;
  background: var(--surface-2);
  border-top: 1px solid var(--line-2);
}

/* ---------- Toast ---------- */
.toast {
  position: fixed; bottom: 28px; left: 50%;
  transform: translateX(-50%);
  background: var(--header-ink); color: #fff;
  font-size: 13px; font-weight: 600;
  padding: 10px 22px; border-radius: 999px;
  box-shadow: 0 10px 30px rgba(10,16,28,.35);
  z-index: 90;
}
.toast.is-bad { background: var(--danger); }
.toast.is-ok { background: var(--ok); }

/* ---------- 页脚 ---------- */
.app-footer {
  display: flex; justify-content: space-between; gap: 16px;
  max-width: 1240px; width: 100%;
  margin: 0 auto;
  padding: 0 28px 22px;
  color: var(--muted); font-size: 12px;
}

@media (max-width: 980px) {
  .layout { grid-template-columns: 1fr; }
  .journey { position: static; }
}

/* ---------- 打印（完成凭证导出） ---------- */
@media print {
  .app-header, .undo-strip, .journey, .app-footer, .drawer, .scrim, .modal, .toast,
  .cert-actions, .crumb .back-btn { display: none !important; }
  body { background: #fff; }
  .layout { display: block; padding: 0; max-width: none; }
  .certificate { box-shadow: none; border: none; padding: 0; }
}

