1	/* 下线指挥台 · 状态机与渲染（无构建、无异步依赖、file:// 可直开） */
2	(function () {
3	  "use strict";
4	
5	  var RUNBOOK = window.RUNBOOK;
6	  var meta = RUNBOOK.meta;
7	
8	  /* ---------- 展平流程 ---------- */
9	  var STEPS = [];
10	  RUNBOOK.phases.forEach(function (phase) {
11	    phase.steps.forEach(function (step) {
12	      STEPS.push(Object.assign({}, step, {
13	        phaseNum: phase.num,
14	        phaseTitle: phase.title,
15	        seq: STEPS.length + 1
16	      }));
17	    });
18	  });
19	  var TOTAL = STEPS.length;
20	  var stepById = {};
21	  STEPS.forEach(function (s) { stepById[s.id] = s; });
22	
23	  /* ---------- 状态 ---------- */
24	  var STORAGE_KEY = "offboard-console-v1";
25	
26	  function freshState() {
27	    return {
28	      startedAt: Date.now(),
29	      pointer: 0,            // 当前步骤索引（唯一推进指针，禁止跳步）
30	      checks: {},            // stepId -> [bool]
31	      done: {},              // stepId -> { at }
32	      irrev: {},             // stepId -> { confirmedAt, executedAt, undoneAt, effectiveAt }
33	      undo: {},              // stepId -> deadline(ms) 活动撤销窗口
34	      deviations: [],        // { at, stepId, kind, text }
35	      events: [],            // { at, kind, text }
36	      selectedStepId: null,  // 旅程图选中（回看已完成步骤）；null = 跟随当前指针
37	      completedAt: null
38	    };
39	  }
40	
41	  function loadState() {
42	    try {
43	      var raw = sessionStorage.getItem(STORAGE_KEY);
44	      if (!raw) return null;
45	      var s = JSON.parse(raw);
46	      if (typeof s.pointer !== "number" || !s.checks) return null;
47	      return s;
48	    } catch (e) { return null; } // file:// 下存储不可用时退化为内存态
49	  }
50	
51	  function saveState() {
52	    try { sessionStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch (e) { /* 内存态 */ }
53	  }
54	
55	  var state = loadState() || freshState();
56	  if (!state.events || !state.events.length) state.startedAt = state.startedAt || Date.now();
57	
58	  // 恢复会话时，把已过期的撤销窗口落为"已生效"
59	  Object.keys(state.undo || {}).forEach(function (id) {
60	    if (Date.now() >= state.undo[id]) finalizeUndoWindow(id, true);
61	  });
62	
63	  /* ---------- 事件与偏差 ---------- */
64	  function logEvent(kind, text) {
65	    state.events.push({ at: Date.now(), kind: kind, text: text });
66	  }
67	  function logDeviation(stepId, kind, text) {
68	    state.deviations.push({ at: Date.now(), stepId: stepId, kind: kind, text: text });
69	    logEvent("deviation", "偏差 +1 · " + text);
70	  }
71	
72	  /* ---------- 工具 ---------- */
73	  function $(id) { return document.getElementById(id); }
74	  function esc(t) {
75	    return String(t).replace(/[&<>"']/g, function (c) {
76	      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
77	    });
78	  }
79	  function fmtTime(ms) {
80	    return new Date(ms).toLocaleTimeString("zh-CN", { hour12: false });
81	  }
82	  function fmtDur(ms) {
83	    var s = Math.max(0, Math.floor(ms / 1000));
84	    var m = Math.floor(s / 60);
85	    s = s % 60;
86	    return (m < 10 ? "0" + m : m) + ":" + (s < 10 ? "0" + s : s);
87	  }
88	  function currentStep() { return STEPS[state.pointer]; }
89	  function isDone(id) { return !!state.done[id]; }
90	  function isCurrent(id) { var c = currentStep(); return !!c && c.id === id; }
91	  function isLocked(id) {
92	    var s = stepById[id];
93	    return !isDone(id) && !isCurrent(id);
94	  }
95	  function stepStatus(id) {
96	    if (isDone(id)) return "done";
97	    if (isCurrent(id)) return "current";
98	    return "locked";
99	  }
100	  function checksOf(step) {
101	    if (!state.checks[step.id]) {
102	      state.checks[step.id] = step.checks.map(function () { return false; });
103	    }
104	    return state.checks[step.id];
105	  }
106	  function checksAllPass(step) {
107	    return checksOf(step).every(Boolean);
108	  }
109	
110	  var ICONS = {
111	    lock: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><rect x="5" y="11" width="14" height="9" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/></svg>',
112	    check: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M5 13l4 4L19 7"/></svg>',
113	    play: '<svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor"><path d="M7 4l13 8-13 8z"/></svg>',
114	    warn: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3L2.5 20h19z"/><path d="M12 10v4"/><path d="M12 17.4v.2"/></svg>',
115	    undo: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 10h11a5 5 0 0 1 0 10h-4"/><path d="M8 6l-4 4 4 4"/></svg>',
116	    checkCircle: '<svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9.5"/><path d="M8 12.5l2.7 2.7L16.5 9"/></svg>'
117	  };
118	
119	  /* ---------- 渲染：顶栏 ---------- */
120	  function renderHeader() {
121	    $("brandSub").textContent = meta.changeId + " · " + meta.title;
