475	  /* ---------- 交互：撤销 ---------- */
476	  function undoStep(id) {
477	    if (!state.undo[id]) return;
478	    var step = stepById[id];
479	    delete state.undo[id];
480	    var rec = state.irrev[id];
481	    if (rec) rec.undoneAt = Date.now();
482	    delete state.done[id];
483	
484	    // 级联回退：该步骤之后所有已完成步骤一并回退（依赖失效）
485	    var rolled = [];
486	    STEPS.slice(step.seq).forEach(function (later) {
487	      if (state.done[later.id]) {
488	        delete state.done[later.id];
489	        delete state.undo[later.id];
490	        rolled.push(later.seq + ". " + later.title);
491	      }
492	    });
493	
494	    state.pointer = step.seq - 1; // 指针退回本步骤
495	    state.selectedStepId = null;
496	    if (state.completedAt) state.completedAt = null;
497	
498	    logEvent("undo", "恢复路径启用：已撤销「" + step.title + "」，状态回到执行前。" +
499	      (rolled.length ? "后续依赖步骤已一并回退：" + rolled.join("、") + "。" : ""));
500	    toast("已撤销：" + step.title, "ok");
501	    saveState();
502	    renderAll();
503	  }
